  lvl({"id":"fp-3","order":85,"topic":"operations","skill":"negatives","band":"adventurer","scene":"ferry","title":{"en":"Cold Snap","ms":"Cuaca Dingin"},"story":{"en":"The temperature rises and falls all day. Work out each change!","ms":"Suhu naik dan turun sepanjang hari. Kira setiap perubahan!"},"learn":{"en":"Add and subtract temperature changes.","ms":"Menambah dan menolak perubahan suhu."},"critter":{"id":"flurryfp","name":{"en":"Flurry","ms":"Flurry"},"blurb":{"en":"Flurry loves a sudden snowfall.","ms":"Flurry sukakan salji yang turun mendadak."},"look":{"body":"drop","c1":"#ffb3f0","c2":"#d26be0","ears":"leaf","feat":"fin","acc":"none"}},"tiers":[{"id":"fp-3-a","type":"steps","prompt":{"en":"Solve each step in order.","ms":"Selesaikan setiap langkah mengikut urutan."},"hint":{"en":"Rises means add. Falls means subtract.","ms":"Naik bermaksud tambah. Turun bermaksud tolak."},"explain":{"en":"4 + 6 = 10, then 10 − 3 = 7, then 7 × 2 = 14.","ms":"4 + 6 = 10, kemudian 10 − 3 = 7, kemudian 7 × 2 = 14."},"spec":{"steps":[{"q":{"en":"It is 4 degrees in the morning. It rises by 6. What is the temperature?","ms":"Suhu pada waktu pagi ialah 4 darjah. Ia naik 6. Berapakah suhu itu?"},"choices":["12","10","8","0"],"answer":1,"calc":"4+6"},{"q":{"en":"Then it falls by 3. What is the temperature?","ms":"Kemudian ia turun 3. Berapakah suhu itu?"},"choices":["6","9","7","2"],"answer":2,"calc":"10-3"},{"q":{"en":"Then it doubles. What is the temperature?","ms":"Kemudian ia menjadi dua kali ganda. Berapakah suhu itu?"},"choices":["114","9","15","14"],"answer":3,"calc":"7*2"}]}},{"id":"fp-3-b","type":"steps","prompt":{"en":"Solve each step in order.","ms":"Selesaikan setiap langkah mengikut urutan."},"hint":{"en":"Take it one step at a time.","ms":"Selesaikan satu langkah pada satu masa."},"explain":{"en":"5 − 12 = −7, then −7 − 3 = −10, then −10 + 15 = 5.","ms":"5 − 12 = −7, kemudian −7 − 3 = −10, kemudian −10 + 15 = 5."},"spec":{"steps":[{"q":{"en":"The peak is 12 degrees below the base. The base is 5 degrees. How many degrees is the peak?","ms":"Puncak 12 darjah lebih rendah daripada pangkalan. Pangkalan 5 darjah. Berapa darjah puncak itu?"},"choices":["−14","−5","−8","−7"],"answer":3,"calc":"5-12"},{"q":{"en":"A storm makes it 3 degrees colder. What is the temperature?","ms":"Ribut menjadikannya 3 darjah lebih sejuk. Berapakah suhu itu?"},"choices":["−20","−10","−15","−7"],"answer":1,"calc":"-7-3"},{"q":{"en":"The sun warms it by 15 degrees. What is the temperature?","ms":"Matahari menghangatkannya sebanyak 15 darjah. Berapakah suhu itu?"},"choices":["105","4","5","8"],"answer":2,"calc":"-10+15"}]}},{"id":"fp-3-c","type":"steps","prompt":{"en":"Solve each step in order.","ms":"Selesaikan setiap langkah mengikut urutan."},"hint":{"en":"Up means add. Down means subtract.","ms":"Naik bermaksud tambah. Turun bermaksud tolak."},"explain":{"en":"100 + 45 = 145, then 145 − 30 = 115, then 115 + 85 = 200.","ms":"100 + 45 = 145, kemudian 145 − 30 = 115, kemudian 115 + 85 = 200."},"spec":{"steps":[{"q":{"en":"A climber starts at 100 m and goes up 45 m. What height is that?","ms":"Seorang pendaki bermula pada 100 m dan naik 45 m. Berapa tinggi itu?"},"choices":["140 m","146 m","145 m","144 m"],"answer":2,"calc":"100+45"},{"q":{"en":"Then goes down 30 m. What height is that?","ms":"Kemudian turun 30 m. Berapa tinggi itu?"},"choices":["116 m","115 m","215 m","125 m"],"answer":1,"calc":"145-30"},{"q":{"en":"Then goes up 85 m. What height is that?","ms":"Kemudian naik 85 m. Berapa tinggi itu?"},"choices":["199 m","205 m","400 m","200 m"],"answer":3,"calc":"115+85"}]}}]});
